const csvDownload=(name,rows)=>{if(!rows.length)return;const keys=Object.keys(rows[0]);const csv=[keys.join(';'),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(';'))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();URL.revokeObjectURL(a.href)};
function Pill({value}){const v=value||'submitted';return <span className={'pill '+v}>{statusLabel[v]||v}</span>}
function Heading({eyebrow,title,desc,action}){return <div className="heading"><div><small>{eyebrow}</small><h1>{title}</h1><p>{desc}</p></div>{action}</div>}
