function Obhs({notify,refresh}){const [rows,setRows]=useState([]),[show,setShow]=useState(false),[edit,setEdit]=useState(null),[f,setF]=useState({name:'',address:'',region:'Banda Aceh',phone:'',email:'',contact_person:'',accreditation_status:'Belum Terakreditasi',accreditation_year:'',is_active:true});const load=useCallback(async()=>{const {data,error}=await supabase.from('obhs').select('*').order('name');if(error)notify(err(error));else setRows(data||[])},[notify,refresh]);useEffect(()=>{load()},[load]);function open(o){setEdit(o||null);setF(o?{...o,accreditation_year:o.accreditation_year||''}:{name:'',address:'',region:'Banda Aceh',phone:'',email:'',contact_person:'',accreditation_status:'Belum Terakreditasi',accreditation_year:'',is_active:true});setShow(true)}async function save(e){e.preventDefault();const payload={...f,accreditation_year:f.accreditation_year?Number(f.accreditation_year):null};const q=edit?supabase.from('obhs').update(payload).eq('id',edit.id):supabase.from('obhs').insert(payload);const {error}=await q;if(error)notify(err(error));else{notify('Data OBH disimpan.');setShow(false);load()}}return <><Heading eyebrow="MASTER DATA" title="Organisasi Bantuan Hukum" desc="Kelola profil, alamat, kontak, personel, dan status akreditasi OBH." action={<button className="btn primary" onClick={()=>open(null)}><Plus size={15}/> Tambah OBH</button>}/><section className="card tablecard"><div className="overflow"><table><thead><tr><th>Nama OBH</th><th>Alamat</th><th>Kab/Kota</th><th>Kontak</th><th>Akreditasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody>{rows.map(o=><tr key={o.id}><td><b>{o.name}</b></td><td>{o.address||'-'}</td><td>{o.region}</td><td>{o.phone||o.email||'-'}</td><td>{o.accreditation_status}{o.accreditation_year?' · '+o.accreditation_year:''}</td><td><Pill value={o.is_active?'verified':'rejected'}/></td><td><button className="link" onClick={()=>open(o)}>Ubah</button></td></tr>)}{!rows.length&&<tr><td colSpan="7" className="emptycell">Belum ada OBH.</td></tr>}</tbody></table></div></section>{show&&<Modal title={edit?'Ubah Profil OBH':'Tambah OBH'} close={()=>setShow(false)}><form className="formgrid" onSubmit={save}><label className="wide">Nama OBH<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label className="wide">Alamat<input value={f.address||''} onChange={e=>setF({...f,address:e.target.value})}/></label><label>Kabupaten/Kota<select value={f.region} onChange={e=>setF({...f,region:e.target.value})}>{regions.map(x=><option key={x}>{x}</option>)}</select></label><label>Nomor kontak<input value={f.phone||''} onChange={e=>setF({...f,phone:e.target.value})}/></label><label>Email<input type="email" value={f.email||''} onChange={e=>setF({...f,email:e.target.value})}/></label><label>Petugas kontak<input value={f.contact_person||''} onChange={e=>setF({...f,contact_person:e.target.value})}/></label><label>Akreditasi<select value={f.accreditation_status} onChange={e=>setF({...f,accreditation_status:e.target.value})}><option>Terakreditasi</option><option>Belum Terakreditasi</option></select></label><label>Tahun akreditasi<input type="number" min="2000" max="2100" value={f.accreditation_year} onChange={e=>setF({...f,accreditation_year:e.target.value})}/></label><label>Status organisasi<select value={String(f.is_active)} onChange={e=>setF({...f,is_active:e.target.value==='true'})}><option value="true">Aktif</option><option value="false">Tidak aktif</option></select></label><div className="modalactions wide"><button className="btn primary">Simpan OBH</button></div></form></Modal>}</>}
function Organization({profile,notify,reload}){const [f,setF]=useState({name:profile.obh?.name||'',address:profile.obh?.address||'',region:profile.obh?.region||'Banda Aceh',phone:profile.obh?.phone||'',email:profile.obh?.email||'',contact_person:profile.obh?.contact_person||'',accreditation_status:profile.obh?.accreditation_status||'Belum Terakreditasi',accreditation_year:profile.obh?.accreditation_year||''}),[members,setMembers]=useState([]),[member,setMember]=useState({full_name:'',position:'Advokat',phone:'',email:''});const load=useCallback(async()=>{const {data,error}=await supabase.from('obh_members').select('*').eq('obh_id',profile.obh_id).order('full_name');if(error)notify(err(error));else setMembers(data||[])},[profile.obh_id]);useEffect(()=>{load()},[load]);async function save(e){e.preventDefault();const {error}=await supabase.from('obhs').update({...f,accreditation_year:f.accreditation_year?Number(f.accreditation_year):null}).eq('id',profile.obh_id);if(error)notify(err(error));else{notify('Profil OBH diperbarui.');reload()}}async function add(e){e.preventDefault();const {error}=await supabase.from('obh_members').insert({...member,obh_id:profile.obh_id});if(error)notify(err(error));else{setMember({full_name:'',position:'Advokat',phone:'',email:''});load();notify('Personel ditambahkan.')}}async function remove(id){if(!confirm('Hapus personel ini?'))return;const {error}=await supabase.from('obh_members').delete().eq('id',id);if(error)notify(err(error));else load()}return <><Heading eyebrow="PROFIL ORGANISASI" title="Profil OBH" desc="Perbarui informasi organisasi dan daftar petugas atau anggota."/><section className="card evalform"><h3>Informasi organisasi</h3><form className="formgrid" onSubmit={save}><label className="wide">Nama OBH<input value={f.name} disabled/></label><label className="wide">Alamat<input value={f.address} onChange={e=>setF({...f,address:e.target.value})}/></label><label>Kabupaten/Kota<select value={f.region} onChange={e=>setF({...f,region:e.target.value})}>{regions.map(x=><option key={x}>{x}</option>)}</select></label><label>Nomor kontak<input value={f.phone} onChange={e=>setF({...f,phone:e.target.value})}/></label><label>Email<input value={f.email} onChange={e=>setF({...f,email:e.target.value})}/></label><label>Petugas kontak<input value={f.contact_person} onChange={e=>setF({...f,contact_person:e.target.value})}/></label><label>Akreditasi<select value={f.accreditation_status} disabled><option>Terakreditasi</option><option>Belum Terakreditasi</option></select></label><label>Tahun akreditasi<input value={f.accreditation_year} disabled/></label><div className="modalactions wide"><button className="btn primary">Simpan profil</button></div></form></section><section className="card evalform"><h3>Petugas / anggota OBH</h3><form className="formgrid" onSubmit={add}><label>Nama lengkap<input required value={member.full_name} onChange={e=>setMember({...member,full_name:e.target.value})}/></label><label>Jabatan / peran<input value={member.position} onChange={e=>setMember({...member,position:e.target.value})}/></label><label>Nomor kontak<input value={member.phone} onChange={e=>setMember({...member,phone:e.target.value})}/></label><label>Email<input type="email" value={member.email} onChange={e=>setMember({...member,email:e.target.value})}/></label><div className="modalactions wide"><button className="btn primary"><Plus size={14}/> Tambah personel</button></div></form><div className="overflow"><table><thead><tr><th>Nama</th><th>Jabatan</th><th>Kontak</th><th>Email</th><th></th></tr></thead><tbody>{members.map(m=><tr key={m.id}><td>{m.full_name}</td><td>{m.position}</td><td>{m.phone}</td><td>{m.email}</td><td><button className="link danger" onClick={()=>remove(m.id)}>Hapus</button></td></tr>)}{!members.length&&<tr><td colSpan="5" className="emptycell">Belum ada personel.</td></tr>}</tbody></table></div></section></>}
function Accounts({notify,refresh}){const [rows,setRows]=useState([]);const load=useCallback(async()=>{const {data,error}=await supabase.from('profiles').select('id,full_name,role,account_status,created_at,obh:obhs(name)').eq('role','obh').order('created_at',{ascending:false});if(error)notify(err(error));else setRows(data||[])},[notify,refresh]);useEffect(()=>{load()},[load]);async function update(p,status){const {error}=await supabase.from('profiles').update({account_status:status}).eq('id',p.id);if(error)notify(err(error));else{notify('Status akun diperbarui.');load()}}return <><Heading eyebrow="MANAJEMEN PENGGUNA" title="Persetujuan Akun OBH" desc="Setujui atau tolak permohonan akun OBH sebelum pengguna dapat mengakses data organisasi."/><section className="card tablecard"><div className="overflow"><table><thead><tr><th>Nama pengguna</th><th>OBH</th><th>Tanggal daftar</th><th>Status</th><th>Aksi</th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td>{p.full_name}</td><td>{p.obh?.name||'-'}</td><td>{dt(p.created_at.slice(0,10))}</td><td><Pill value={p.account_status==='active'?'verified':p.account_status==='rejected'?'rejected':'submitted'}/></td><td><div className="rowactions"><button title="Setujui" onClick={()=>update(p,'active')}><Check size={14}/></button><button title="Tolak" onClick={()=>update(p,'rejected')}><X size={14}/></button></div></td></tr>)}{!rows.length&&<tr><td colSpan="5" className="emptycell">Belum ada permohonan akun.</td></tr>}</tbody></table></div></section></>}
function Reports({admin,profile,notify,refresh}){const [rows,setRows]=useState([]),[obhs,setObhs]=useState([]),[show,setShow]=useState(false),[file,setFile]=useState(null),[f,setF]=useState({obh_id:profile.obh_id||'',period_type:'Triwulan',period_year:String(new Date().getFullYear()),period_number:'1',title:'',description:''});const load=useCallback(async()=>{let q=supabase.from('report_submissions').select('*,obh:obhs(name)').order('created_at',{ascending:false});if(!admin)q=q.eq('obh_id',profile.obh_id);const [r,o]=await Promise.all([q,admin?supabase.from('obhs').select('id,name').eq('is_active',true):Promise.resolve({data:[]})]);if(r.error)notify(err(r.error));else setRows(r.data||[]);setObhs(o.data||[])},[admin,profile.obh_id,notify,refresh]);useEffect(()=>{load()},[load]);async function submit(e){e.preventDefault();try{if(!file)throw Error('Pilih dokumen PDF atau Excel.');if(file.size>10*1024*1024)throw Error('Ukuran file maksimal 10 MB.');const {data:{user}}=await supabase.auth.getUser();const obhId=admin?f.obh_id:profile.obh_id;if(!obhId)throw Error('Pilih OBH.');const path=`${obhId}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await supabase.storage.from('sipbh-private').upload(path,file,{upsert:false});if(up.error)throw up.error;const {error}=await supabase.from('report_submissions').insert({obh_id:obhId,submitted_by:user.id,period_type:f.period_type,period_year:Number(f.period_year),period_number:f.period_type==='Tahunan'?null:Number(f.period_number),title:f.title||`Laporan ${f.period_type}`,description:f.description,file_path:path});if(error)throw error;notify('Laporan berhasil diunggah.');setShow(false);setFile(null);load()}catch(e){notify(err(e))}}async function review(r,status){const note=prompt(status==='accepted'?'Catatan penerimaan (opsional):':'Catatan perbaikan/penolakan:','');if(status!=='accepted'&&!note)return;const {data:{user}}=await supabase.auth.getUser();const {error}=await supabase.from('report_submissions').update({status,admin_note:note||null,reviewed_by:user.id,reviewed_at:new Date().toISOString()}).eq('id',r.id);if(error)notify(err(error));else{notify('Status laporan diperbarui.');load()}}async function download(r){const {data,error}=await supabase.storage.from('sipbh-private').createSignedUrl(r.file_path,60);if(error)notify(err(error));else window.open(data.signedUrl,'_blank','noopener,noreferrer')}return <><Heading eyebrow="PELAPORAN" title="Laporan Berkala" desc="Unggah laporan OBH dan pantau hasil verifikasi. Laporan otomatis dapat diekspor dari dashboard." action={<div className="actions"><button className="btn" onClick={async()=>{let q=supabase.from('assistance_services').select('registration_no,service_date,service_type,case_type,activity_type,region,service_amount,status,obh:obhs(name),beneficiary:beneficiaries(beneficiary_code)').order('service_date',{ascending:false});if(!admin)q=q.eq('obh_id',profile.obh_id);const {data,error}=await q;if(error)notify(err(error));else csvDownload('rekapitulasi-pbh-'+new Date().getFullYear()+'.csv',(data||[]).map(x=>({nomor:x.registration_no,tanggal:x.service_date,obh:x.obh?.name,jenis:x.service_type,kasus_kegiatan:x.case_type||x.activity_type,wilayah:x.region,kode_penerima:x.beneficiary?.beneficiary_code,nominal:x.service_amount,status:statusLabel[x.status]})))}}><FileSpreadsheet size={15}/> Rekap otomatis CSV</button><button className="btn primary" onClick={()=>setShow(true)}><Upload size={15}/> Unggah laporan</button></div>}/><section className="card tablecard"><div className="overflow"><table><thead><tr><th>Judul laporan</th>{admin&&<th>OBH</th>}<th>Periode</th><th>Tanggal unggah</th><th>Status</th><th>Dokumen</th>{admin&&<th>Review</th>}</tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><b>{r.title}</b><small className="subcell">{r.description}</small></td>{admin&&<td>{r.obh?.name}</td>}<td>{r.period_type} {r.period_number?` ${r.period_number}`:''} / {r.period_year}</td><td>{dt(r.created_at.slice(0,10))}</td><td><Pill value={r.status}/></td><td><button className="link" onClick={()=>download(r)}><Download size={13}/> Unduh</button></td>{admin&&<td><div className="rowactions"><button title="Terima" onClick={()=>review(r,'accepted')}><Check size={14}/></button><button title="Minta perbaikan" onClick={()=>review(r,'revision')}><RefreshCw size={14}/></button><button title="Tolak" onClick={()=>review(r,'rejected')}><X size={14}/></button></div></td>}</tr>)}{!rows.length&&<tr><td colSpan={admin?7:5} className="emptycell">Belum ada laporan.</td></tr>}</tbody></table></div></section>{show&&<Modal title="Unggah Laporan Berkala" close={()=>setShow(false)}><form className="formgrid" onSubmit={submit}>{admin&&<label className="wide">OBH<select required value={f.obh_id} onChange={e=>setF({...f,obh_id:e.target.value})}><option value="">Pilih OBH</option>{obhs.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select></label>}<label>Jenis periode<select value={f.period_type} onChange={e=>setF({...f,period_type:e.target.value,period_number:e.target.value==='Tahunan'?'': '1'})}><option>Triwulan</option><option>Semester</option><option>Tahunan</option></select></label><label>Tahun<input type="number" min="2000" max="2100" required value={f.period_year} onChange={e=>setF({...f,period_year:e.target.value})}/></label>{f.period_type!=='Tahunan'&&<label>Periode<select value={f.period_number} onChange={e=>setF({...f,period_number:e.target.value})}>{(f.period_type==='Triwulan'?[1,2,3,4]:[1,2]).map(x=><option key={x} value={x}>{f.period_type} {x}</option>)}</select></label>}<label className="wide">Judul laporan<input value={f.title} onChange={e=>setF({...f,title:e.target.value})} placeholder="Contoh: Laporan Pelaksanaan PBH Triwulan I"/></label><label className="wide">Keterangan<textarea rows="2" value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><label className="wide">Dokumen PDF / Excel<input type="file" accept=".pdf,.xlsx,.xls,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" required onChange={e=>setFile(e.target.files?.[0]||null)}/><small className="subcell">Maksimal 10 MB. Disimpan di private storage.</small></label><div className="modalactions wide"><button className="btn primary">Kirim laporan</button></div></form></Modal>}</>}
function Evaluation({admin,profile,notify,refresh}){const [services,setServices]=useState([]),[rows,setRows]=useState([]),[selected,setSelected]=useState(''),[scores,setScores]=useState({'Aksesibilitas layanan':5,'Responsivitas OBH':5,'Kualitas pendampingan':5,'Ketepatan waktu layanan':5,'Kepuasan penerima':5}),[notes,setNotes]=useState('');const criteria=Object.keys(scores);const load=useCallback(async()=>{let q=supabase.from('assistance_services').select('id,registration_no,service_date,service_type,obh:obhs(name),beneficiary:beneficiaries(full_name,beneficiary_code)').eq('status','verified').order('service_date',{ascending:false});if(!admin)q=q.eq('obh_id',profile.obh_id);const [s,e]=await Promise.all([q,supabase.from('service_evaluations').select('*,scores:evaluation_scores(score),service:assistance_services(registration_no,obh:obhs(name))').order('created_at',{ascending:false})]);if(s.error)notify(err(s.error));else setServices(s.data||[]);if(e.error)notify(err(e.error));else setRows(e.data||[])},[admin,profile.obh_id,notify,refresh]);useEffect(()=>{load()},[load]);async function save(e){e.preventDefault();try{const {data:{user}}=await supabase.auth.getUser();const {data,error}=await supabase.from('service_evaluations').insert({service_id:selected,evaluated_by:user.id,notes}).select('id').single();if(error)throw error;const payload=criteria.map(c=>({evaluation_id:data.id,criterion:c,score:Number(scores[c])}));const ins=await supabase.from('evaluation_scores').insert(payload);if(ins.error)throw ins.error;notify('Evaluasi layanan berhasil disimpan.');setSelected('');setNotes('');load()}catch(e){notify(err(e))}}return <><Heading eyebrow="PENJAMINAN MUTU" title="Evaluasi Layanan" desc={admin?'Lakukan penilaian terhadap layanan yang telah diverifikasi.':'Lihat hasil evaluasi layanan dari Admin Kanwil.'}/>{admin&&<section className="card evalform"><h3>Instrumen evaluasi layanan</h3><p>Skor 1 (Perlu Pembinaan) sampai 5 (Sangat Baik). Sesuaikan indikator dengan instrumen resmi penelitian.</p><form className="formgrid" onSubmit={save}><label className="wide">Layanan terverifikasi<select required value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Pilih layanan</option>{services.map(s=><option key={s.id} value={s.id}>{s.registration_no} · {s.beneficiary?.beneficiary_code||s.beneficiary?.full_name} · {s.obh?.name}</option>)}</select></label>{criteria.map(c=><label key={c}>{c}<select value={scores[c]} onChange={e=>setScores({...scores,[c]:Number(e.target.value)})}>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} · {['','Perlu Pembinaan','Kurang','Cukup','Baik','Sangat Baik'][n]}</option>)}</select></label>)}<label className="wide">Catatan evaluasi<textarea rows="3" value={notes} onChange={e=>setNotes(e.target.value)}/></label><div className="modalactions wide"><button className="btn primary">Simpan evaluasi</button></div></form></section>}<section className="card tablecard"><div className="sectiontitle"><h3>Riwayat evaluasi</h3></div><div className="overflow"><table><thead><tr><th>Nomor layanan</th><th>OBH</th><th>Rata-rata</th><th>Kategori</th><th>Catatan</th><th>Tanggal</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td className="mono">{r.service?.registration_no}</td><td>{r.service?.obh?.name}</td><td>{r.scores?.length?(r.scores.reduce((a,x)=>a+x.score,0)/r.scores.length).toFixed(1)+'/5':'-'}</td><td>{r.scores?.length?(r.scores.reduce((a,x)=>a+x.score,0)/r.scores.length>=4.5?'Sangat Baik':r.scores.reduce((a,x)=>a+x.score,0)/r.scores.length>=3.5?'Baik':r.scores.reduce((a,x)=>a+x.score,0)/r.scores.length>=2.5?'Cukup':'Perlu Pembinaan'):'Belum dinilai'}</td><td>{r.notes||'-'}</td><td>{dt(r.created_at.slice(0,10))}</td></tr>)}{!rows.length&&<tr><td colSpan="6" className="emptycell">Belum ada evaluasi.</td></tr>}</tbody></table></div></section></>}
export default App;
